for sex in ('Male','Female'):
 bpy.ops.wm.open_mainfile(filepath=str(O/f'{sex}_ReferenceBody_Smooth.blend'));rig=next(o for o in bpy.data.objects if o.type=='ARMATURE');body=bpy.data.objects['Body'];data={'unitScale':bpy.context.scene.unit_settings.scale_length,'unitSystem':bpy.context.scene.unit_settings.system,'groups':[g.name for g in body.vertex_groups],'bodyWorld':[list(v) for v in body.matrix_world],'rigWorld':[list(v) for v in rig.matrix_world],'rigRest':rig.data.pose_position,'modifiers':[(m.name,m.type,m.object.name if m.type=='ARMATURE' and m.object else '') for m in body.modifiers],'bones':{b.name:[list(v) for v in b.matrix_local] for b in rig.data.bones},'bodyBounds':[list(v) for v in body.bound_box]}
 bpy.ops.wm.read_factory_settings(use_empty=True);bpy.ops.import_scene.fbx(filepath=str(O/f'{sex}_ReferenceBody_Smooth.fbx'));rig=next(o for o in bpy.data.objects if o.type=='ARMATURE');body=next(o for o in bpy.data.objects if o.type=='MESH' and o.name=='Body');data['reimport']={'unitScale':bpy.context.scene.unit_settings.scale_length,'groups':[g.name for g in body.vertex_groups],'bodyWorld':[list(v) for v in body.matrix_world],'rigWorld':[list(v) for v in rig.matrix_world],'boneCount':len(rig.data.bones),'bones':{b.name:[list(v) for v in b.matrix_local] for b in rig.data.bones},'bodyBounds':[list(v) for v in body.bound_box],'groupsBad':[g.name for g in body.vertex_groups if g.name not in rig.data.bones]};out[sex]=data
(O/'export-rig-audit.json').write_text(json.dumps(out,indent=2));print('EXPORT_AUDIT',[(s,d['unitScale'],len(d['groups']),d['reimport']['boneCount'],d['reimport']['groupsBad']) for s,d in out.items()])
